/// Daily reflection notifications from «جام و میگر اول».
class DailyReflection {
  const DailyReflection({
    required this.id,
    required this.title,
    required this.body,
    required this.source,
  });

  final int id;
  final String title;
  final String body;
  final String source;

  String get notificationBody {
    final text = body.trim();
    if (text.length <= 220) return text;
    return '${text.substring(0, 217)}…';
  }
}

const List<DailyReflection> dailyReflections = [
  DailyReflection(id: 1, title: 'بیرون کشیدن از عدم', body: 'اگر خداوند جل‌جلاله ما را از آنجا (عدم) بيرون نمی‌کشيد و به اين احسن صورت نمی‌‌آفريد، باری چه می‌بوديم؟\n]لَقَدْ خَلَقْنَا الْإِنْسانَ فِي أَحْسَنِ تَقْوِيمٍ[', source: 'جام و میگر اول'),
  DailyReflection(id: 2, title: 'پیدایش بشکل سنگ، ریگ', body: 'اگر مشيتِ الله جل‌جلاله بر پيدايش ما رفته بود، هرگاه ما را در سلسله جمادات ازقبيل سنگ يا ريگ، معادن يا درخت و غيره اثمار، حبوبات، سبزیجات و هزاران نمونه از اشيای ديگر می‌کشيدند، چه می‌نموديم؟ دقت کنند! تسليم شويم که ما را اراده کرده بودند تا جاندار خلق کنند.', source: 'جام و میگر اول'),
  DailyReflection(id: 3, title: 'پیدایش در جمع حیوانات', body: 'اگر در قطار ده‌ها‌هزار ماشين جاندار، ما را به‌شکل غير انسان مثل میکروب، پشه و انتها گوسفند، بز، اسپ، فيل، نهنگ و يا غيره طيور در بر و بحر يا به اشکال موجودات ديگر می‌‌برآوردند، باز چه می‌شد؟', source: 'جام و میگر اول'),
  DailyReflection(id: 4, title: 'پیدایش در ادیان باطله', body: 'اگر خداوند جل‌جلاله ما را به اديان باطله و يا روش‌های فاسده مزخرف چون آتش‌پرستی، زردشتی و غيره مسالک و حتی به سلسله بی‌خدايی و انکار از وجود حضرت باری خويش می‌‌آفريد، باز چه می‌شد؟', source: 'جام و میگر اول'),
  DailyReflection(id: 5, title: 'توفیق تحصیل علم', body: 'اگر خداوند جل‌جلاله به ما توفيق تحصيل علم و لياقت دريافت آن را نمی‌داد، باری همين عبارت تحت مطالعه و اسرار و انوار حاصله از آن را چطور درک کرده می‌توانـستيم؟ بايد دقت کنيم. بیایید کمی پائین‌تر بنگريم.', source: 'جام و میگر اول'),
  DailyReflection(id: 6, title: 'توفیق حیات', body: 'اگر خداوند جل‌جلاله هنگام آمدن از عدم به صُلب پدر و از آنجا به تاريکستان رَحِم مادر، در بين میليون‌ها مثل ما اسپرما يا ذرۀ منی که از يک دانۀ آن ما را خلق و متباقی نابود شدند، بدان سلسله محو و در قطار معدوم‌شوندگان می‌آورد، باز چه می‌شد؟', source: 'جام و میگر اول'),
  DailyReflection(id: 7, title: 'توفیق اعضای سلیم', body: 'اگر خداوند جل‌جلاله ما را در بطن مادر به سيمای بد يا معيوب خلق می‌کرد که از چشم يا غيره اعضاء معذور می‌بوديم، باز چه می‌شد؟', source: 'جام و میگر اول'),
  DailyReflection(id: 8, title: 'توفیق بیرون برآمدن از رحم مادر', body: 'اگر خداوند جل‌جلاله طفل را از رحم به لطف و کرم خويش با آنهمه کلانی و بی‌تناسبی که با دروازه مخرج دارد، خودبه‌خود بيرون نمی‌کرد و اين را انسان‌ها به پاره کردن شکم می‌کشيدند، آيا چه می‌شد؟ و چه می‌کرديم؟ و کدام زن به پاره شدن شکم حاضر می‌گرديد؟ و اگر می‌شد به چه تکليف مواجه می‌گشت و تحمل اين بار گران را چه کس می‌نمود؟', source: 'جام و میگر اول'),
  DailyReflection(id: 9, title: 'وفات در امراض گوناگون', body: 'اگر در آوان صغارت مثل اطفال همسن ما، ما را به امراض گوناگون از بين می‌بردند يا مفلوج، معذور، بی‌سواد و بی‌دانش می‌داشتند، باز چه می‌شد؟', source: 'جام و میگر اول'),
  DailyReflection(id: 10, title: 'حیات در آغوش فامیل و اقارب', body: 'اگر خداوند جل‌جلاله حيات ما را به آغوش گرم مادر و پدر بسر نمی‌آورد و يا به ديگر محدثات امور، محتاج مزدوری به دروازه‌های مردم می‌بوديم، باز چه می‌شد؟', source: 'جام و میگر اول'),
  DailyReflection(id: 11, title: 'حکمت پهن بودن سیستم عصبی', body: 'اگر در بدن ما اعصاب به‌حکم تلفون به هر جانب پهن نمی‌بود، آيا به روزی چند بار به اثر ضربه‌های سنگ و چوب، و رفتن ميخ و سوزن و غيره اشياء، ما چه زخم‌های بی‌شماری در جسم برمی‌داشتيم و تا وقتی که خبر می‌شديم، آنجا خودبه‌خود پوسيده و سياه گشته می‌بود، در آن صورت چه می‌شد؟', source: 'جام و میگر اول'),
  DailyReflection(id: 12, title: 'حکمت وجود حافظه', body: 'اگر خدای متعال جل‌جلاله حافظه را برای ما نمی‌داد، آيا از اشياء و گفتاری که به ما گفته شده بود و به جايی مايل بوديم که بگوييم، باز از چه استفاده می‌کرديم و چه قسمت را يادآوری نموده می‌توانـستيم؟ لذا ارسال و مرسول بايد بکلی قطع و هرکس شخصاً طرف ضرورت را به جا و محلش ديده، به او سخن خود را می‌گفت.', source: 'جام و میگر اول'),
  DailyReflection(id: 13, title: 'عقل محدود', body: 'اگر خداوند جل‌جلاله به ما انسان‌ها مثل حيوانات بزرگ يا کوچک، عقل محدود به نام شعور می‌داد که فقط توالد و تناسل و از دشمن احتياط کردن با غيره مشخصات معين را می‌فهمیديم و بيشتر نمی‌دانستيم، آيا ما چه می‌بوديم و چه می‌کرديم؟', source: 'جام و میگر اول'),
  DailyReflection(id: 14, title: 'حکمت چرب و ناشکن بودن مو های سر و بدن', body: 'اگر خداوند جل‌جلاله موهای سر و بدن را به‌طور مناسب، هميشه چرب و از جنس ناشکن خلق نمی‌کرد، لازم بود که ما خود همواره آن را چرب می‌کرديم تا نشکنند، در اين صورت چه حالت می‌داشتيم و چه کسانی از عهده اين کار برآمده می‌توانستند و اين زيبايی را به چه تکليف نگاه کرده می‌توانـستيم؟', source: 'جام و میگر اول'),
  DailyReflection(id: 15, title: 'وجود موی‌دار', body: 'اگر خداوند جل‌جلاله وجود انسان‌ها را مانند گوسفند موی‌دار می‌ساخت، باز چه می‌شد؟', source: 'جام و میگر اول'),
  DailyReflection(id: 16, title: 'حکمت بلند شدن مو های بدن', body: 'اگر خدای متعال موهاي بدن ما را اتوماتیک به ترتيب و اندازۀ لازم بلند نمی‌کرد، برعکس کش کردن و دراز نمودن تار تار آن به ما تعلق می‌داشت، در آن صورت چه می‌شد و چه می‌کرديم؟ خصوصاً اگر کش نمی‌شد باز چه می‌نموديم؟', source: 'جام و میگر اول'),
  DailyReflection(id: 17, title: 'حکمت رشد اندک مو های پلک و بدن و ابرو', body: 'اگر خدای متعال موی پلک و بدن و ابرو را مثل موی ريش، سر و غیره اعضای معين هميشه رشد می‌داد، آيا در کوتاه و بلند کردن و مود کشيدن آن‌ها به چه تکليف روبرو می‌بوديم؟', source: 'جام و میگر اول'),
  DailyReflection(id: 18, title: 'حکمت وجود پلک و ابرو', body: 'اگر خدای متعال موی پلک و ابرو را به انسان عنايت نمی‌کرد، آيا می‌دانيد که قشنگ‌ترين انسان چقدر بدقواره معلوم می‌گرديد؟', source: 'جام و میگر اول'),
  DailyReflection(id: 19, title: 'حکمت ناشکن بودن مو های ابرو و پلک', body: 'اگر موهاي ابرو و پلک شکنند می‌بود، بايد به چرب کردن آن از جنس روغن خوب و خراب استفاده می‌کرديم و زمانی که فراموش می‌شد موهاي مذکور می‌شکست و می‌ريخت، در آن حال چه وضع و چه چهره می‌داشتيم؟', source: 'جام و میگر اول'),
  DailyReflection(id: 20, title: 'حکمت عدسيۀ چشم', body: 'اگر خدای عظيم داخل عدسيۀ چشم را آنقدر به حکمت، وسيع برای انلارج عکس اشياء خلق نمی‌کرد و يا به اندازۀ مردمک چشم که داريم می‌ديديم، آيا به براندازی يک متر جای تا چند ساعت بايد کلۀ خود را دور داده و آن را سراپا ديده می‌توانـستيم، باز چه می‌کرديم؟', source: 'جام و میگر اول'),
  DailyReflection(id: 21, title: 'رطوبت لازمه چشم', body: 'اگر خداوند جل‌جلاله چشم‌ ما را به‌طور اتوماتيک با رطوبت لازمه هميشه مرطوب نداشته و خودبه‌خود نشيب‌وفراز نمی‌کرد، آيا تصور می‌کنيد که در آن صورت چه می‌شد و چه می‌کرديم؟', source: 'جام و میگر اول'),
  DailyReflection(id: 22, title: 'توانایی چشم انسان در مقابل روشنایی آفتاب', body: 'اگر خداوند متعال جل‌جلاله چشم انسان‌ها را در مقابل روشنايی آفتاب طاقت و توان نمی‌داد و ما مثل شب‌پرک‌های بال‌چرمی‌ (خفاش) از طرف روز در غارها می‌بوديم و از طرف شب بيرون می‌شديم، باری حال ما چه می‌بود؟', source: 'جام و میگر اول'),
  DailyReflection(id: 23, title: 'حکمت موجودیت دو چشم', body: 'اگر خداوند جل‌جلاله ما انسان‌ها را يک‌چشمه می‌‌آفريد و آن را هم بالای کلۀ ما جای می‌داد، باز چه می‌شد و به چه تکليف پيش روی خود را ديده و يا غيره کارهای خود را انجام می‌داديم؟', source: 'جام و میگر اول'),
  DailyReflection(id: 24, title: 'حکمت استفاده از استخوان غضروفی در بینی و گوش', body: 'اگر خداوند جل‌جلاله بينی و گوش‌های ما را از جنس استخوان غضروفی يعنی ککرکی نمی‌ساخت، آيا درک می‌کنيد که به هر شب گوش‌ها و بينی ما می‌شکست و يا اينکه تخته به پشت خود را چهارميخ کرده بايد خواب می‌شديم تا به پهلو يا به روی نه‌غلطيم که مبادا گوش و بينی ما نشکند.', source: 'جام و میگر اول'),
  DailyReflection(id: 25, title: 'حکمت توازن شنوایی گوش ها', body: 'اگر خداوند جل‌جلاله حس شنوايی ما را به اندازۀ ضعيف عيار می‌کرد، تا شخص گوينده به گوش ما نمی‌گفت سخن او را شنيده نمی‌توانستيم، باز چه می‌شد و حال ما چه می‌بود؟', source: 'جام و میگر اول'),
  DailyReflection(id: 26, title: 'حکمت موجودیت مو های درون بینی', body: 'اگر خدای متعال جل‌جلاله موهای درون بينی را رشد نمی‌داد و يا هيچ نمو نمی‌کرد، آيا به يک نفس کشيدن، چقدر خاک و گرد در آن داخل می‌شد و به کجا می‌رسيد؟ و اگر رشد آن غلو می‌داشت به چه تکاليف بازهم گرفتار می‌بوديم؟ که آب بينی آن را بهم چسپانيده راه تنفس را طبيعی بند می‌کرد.', source: 'جام و میگر اول'),
  DailyReflection(id: 27, title: 'خلقت صورت زیبای انسان', body: 'اگر خداوند جل‌جلاله ما انسان‌ها را خرطوم‌دار مثل فيل می‌‌آفريد، در آن صورت يک دست دريشی خود را که به قيمت گزاف هم می‌ساختيم، در آن قواره و تيپ ما چطور معلوم می‌شد؟', source: 'جام و میگر اول'),
  DailyReflection(id: 28, title: 'درک و درایت دندان ها', body: 'اگر دندان‌ها اين درک و درايت عصبی خاص را نمی‌داشتند، آيا در هنگام خوردن غذا، چقدر سنگريزه‌‌ها را خاييده می‌خورديم؟ باآنکه دکتوران گويند در استخوان عصب نيست.', source: 'جام و میگر اول'),
  DailyReflection(id: 29, title: 'حکمت خلقت دندان از استخوان های متفاوت', body: 'اگر خداوند جل‌جلاله دندان‌های انسان را همه از يک‌ توته استخوان خلق می‌کرد؟', source: 'جام و میگر اول'),
  DailyReflection(id: 30, title: 'حکمت موجودیت دهن', body: 'اگر خداوند جل‌جلاله انسان را به‌جای دهن، منقار (نول) مثل پرند‌گان می‌داد که به غير از دانه ديگر چيز را خورده نمی‌توانستیم، باز چه می‌شد؟ و اگر می‌خورديم به چه زحمت روبرو می‌بوديم؟', source: 'جام و میگر اول'),
  DailyReflection(id: 31, title: 'چشم های زبان و درک آن', body: 'اگر خدای متعال برای زبان دو چشم مخصوص و درک جداگانۀ حساس نمی‌داد که هنگام لقمه خاييدن آن را از چپ به راست برده و به زير آسياب دندان‌ها تيله کرده، جايدار می‌سازد و اين عمل را نه يک ‌بار بلکه به هر بار خاييدن تکرار می‌نمايد و از اطراف دهن طعام را جمع کرده، برای جويدن به زير دندان‌های طواحِن و غیره می‌رساند.', source: 'جام و میگر اول'),
  DailyReflection(id: 32, title: 'حکمت چشم های بیدار زبان', body: 'اگر زبان چشم بيدار در اين غار (دهن) با زرنگی تمام در کار نمی‌داشت، بدين صورت به هر نان خوردن، نصف زبان قسماً زخمی و به زير دندان‌ها می‌شد و اگر اين عمل را به‌واسطۀ انگشت اجرا می‌کرديم، انگشت ما به يک يا دو بار و آنهم به‌شرطی‌که هنگام لقمه خاييدن در دهن باشد، زخم می‌گرديد.', source: 'جام و میگر اول'),
  DailyReflection(id: 33, title: 'نعمت قوۀ‌ نطق و تحریر', body: 'اگر خداوند جل‌جلاله قوۀ‌ نطق و تحرير را به انسان ارزانی نمی‌کرد، آيا با اين عقل منکشف به چه تکاليف روبرو می‌بود؟ زيرا آرزو می‌داشت بگويد، گفته نمی‌توانست و می‌خواست تا وصيت يا امرش به جای دور تعميل گردد، ولی راز رسم‌الخط را نمی‌دانست، پس چه بايد می‌کرد و چطور حل مشکلات را برای جای دور می‌نمود؟ آن وقت چه می‌شد؟', source: 'جام و میگر اول'),
  DailyReflection(id: 34, title: 'حکمت فرورفتن اتوماتیک غذا', body: 'اگر در گلوی ما به امر خدای متعال به‌طور اتوماتیک، نان خود‌به‌خود فرو نمی‌رفت و هريک از ما به گلوی همديگر به‌واسطۀ سيخ و يا کدام چيزی مثل آن طعام را فرو می‌برديم، باری چه حال می‌بود و چه وضع می‌داشتيم؟', source: 'جام و میگر اول'),
  DailyReflection(id: 35, title: 'حکمت قرارگرفتن قلب در قفس سینه', body: 'اگر خداوند متعال جل‌جلاله قلب را در قفس سينه جای نمی‌داد و بيرون سينه خلق می‌کرد و ارتباطش توسط شريان و وريدها از اندرون وجود می‌بود، باری محافظت اين عضو مهم از تکر شدن و غیره چيزها چطور ممکن می‌شد؟ و در نگهداری آن چه حال می‌داشتيم و به چه تکاليف مواجه می‌بوديم؟', source: 'جام و میگر اول'),
  DailyReflection(id: 36, title: 'حکمت پمپ کردن اتوماتیک قلب', body: 'اگر پمپ کردن قلب توسط خود ما اجرا می‌شد و بايد هميشه آن را فشار می‌داديم، باری چه کار مشکل بود و چه می‌بوديم و هنگام کار و مصروفيت چه می‌کرديم؟', source: 'جام و میگر اول'),
  DailyReflection(id: 37, title: 'حکمت موجودیت دست و یا انگشتان', body: 'اگر خداوند جل‌جلاله انسان را دست و يا انگشتان نمی‌داد، باز چه حال داشتيم و اشیاء را به چه تکليف گرفته به دهن می‌برديم؟', source: 'جام و میگر اول'),
  DailyReflection(id: 38, title: 'تصفیه اتومات آب فضله معده به‌واسطه گرده ها', body: 'اگر خداوند جل‌علی‌شأنه آب ‌فضله را از معده به‌واسطه گرده‌‌ها اتومات تصفيه و جدا نمی‌کرد و اين کار به قسمی از اقسام به ما تعلق می‌داشت، باز چه می‌شد؟', source: 'جام و میگر اول'),
  DailyReflection(id: 39, title: 'حکمت انقباض و انبساط معده', body: 'اگر نان در معده به‌واسطه فشار دادن خود ما بايد حرکت پيدا می‌کرد، مثلی‌که حالا اتوماتيک معده آن را تا چهار ساعت فشاری به نام‌های انقباض و انبساط می‌دهد، اين کار به ما چقدر تکليف‌آور بود؟ دقت شود.', source: 'جام و میگر اول'),
  DailyReflection(id: 40, title: 'حکمت هضم انواع غذا ها', body: 'اگر خداوند جل‌جلاله معدۀ انسان را تنها برای حل چيزهای ضعيف مثل نان‌جواری و يا کدام چيز بسيط ديگر آماده می‌کرد و ديگر نعماء را حل و هضم کرده نمی‌توانست، حالا کجا از اين‌همه نعمای بی‌حساب استفاده کرده می‌توانستيم؟', source: 'جام و میگر اول'),
  DailyReflection(id: 41, title: 'عمل نفخ متعفن روده‌ها', body: 'اگر نفخ متعفن روده‌ها که از اثر طعام و خوراک گوناگون پيدا می‌شود، نظر به کیفیت خود جانب بالا آمده و از راه دهن خارج می‌شد، در آن صورت حالت ما چه می‌بود؟ باآنکه خاصيت باد و هواست که جانب بالا خصوصاً که گرم شود می‌رود، دقت کنيد! اکنون نفخ متعفن روده‌ها برعکس جانب پائین خلاف خاصیت خود می‌رود.', source: 'جام و میگر اول'),
  DailyReflection(id: 42, title: 'بند و باز شدن اتوماتیک سیستم اطراحیه', body: 'اگر هردو راه (پيش ‌و پس) اتوماتيک بند و باز نمی‌شدند، آيا حالت ما چه می‌بود؟', source: 'جام و میگر اول'),
  DailyReflection(id: 43, title: 'دفع مواد فاضله بصورت اتوماتیک', body: 'اگر غايطه و بول خودبه‌خود به وقت لازم به‌طور اتومات از مخرجين دفع نمی‌شد و لازم می‌بود که شخصی معده ما را فشار می‌داد تا مواد فضله می‌برآمد، در آن صورت چه حالت می‌داشتيم و يا اگر به دست و يا طور ديگر می‌کشيديم، چه می‌شد؟', source: 'جام و میگر اول'),
  DailyReflection(id: 44, title: 'حکمت عمل قبض', body: 'اگر خداوند جل‌جلاله به هفته، ماه يا سال، يک يا چند بار قبض ادرار و غايطه را به انسان مواجه می‌کرد، در آن حال چه می‌بود و چه می‌کرديم؟ يعنی به سالی چند بار راه‌های پيش ‌و پس انسان‌ها بند می‌شد، به چه تکاليف دچار می‌بوديم؟', source: 'جام و میگر اول'),
  DailyReflection(id: 45, title: 'نداشتن دم', body: 'اگر خداوند جل‌جلاله انسان را نيز دُم دراز و از يک تکه استخوان می‌داد که امکان قات کردن هم نمی‌داشت، باز چطور می‌شد؟ و آن را در بين ايزار يا پطلون چگونه جای می‌کرديم و بر آن چطور می‌‌نشستيم؟ مگر از موجودان دارای اين شکل چه امتياز داشتيم، بجز فضل و احسان او جل‌جلاله؟', source: 'جام و میگر اول'),
  DailyReflection(id: 46, title: 'گوسفندان دنبۀ کلان', body: 'اگر خداوند جل‌جلاله بشر را مثل گوسفندان دنبۀ کلان می‌داد، دقت نماييد حال ما چه می‌بود؟ آخر غور کنيد که خلقت اين صورت‌ها ناممکن است؟ نه، هرگز. به‌روی کدام لياقت مفتخر به ]لَقَد خَلَقنَا الاِنسَانَ فِی اَحسَنِ تَقوِيم[ کرده و ما را به اين دولت سزاوار نموده، به فضل آفريدند؟', source: 'جام و میگر اول'),
  DailyReflection(id: 47, title: 'حکمت موازنه و اندازه طاقت استخوان ها', body: 'اگر خداوند جل‌جلاله موازنه و اندازۀ طاقت استخوان‌ها را از روی برداشت موازنۀ جسم عيار نمی‌کرد، به‌اين‌حساب که مفصل زيرين پای يعنی استخوان زير بجلک، از همه قوی‌تر و طاقت‌ورتر و قوت برداشت ده تا پانزده سير وزن جسم را نمی‌داشت، به چه سرعت استخوان‌ها سايیده و انسان از رفتار باز می‌ماند؟', source: 'جام و میگر اول'),
  DailyReflection(id: 48, title: 'قوت استخوان های زانو', body: 'اگر خداوند جل‌جلاله استخوان‌های زانو را به طاقت موازنه مذکور به قوت کافی قوی خلق نمی‌‌نمود (اينچنين بالاتر از آن مفاصل کمر و غيره) در اين صورت به هر روز يا هفته يا لااقل ماه يک ‌بار استخوان‌ها سايیده شده، به چه زحمت و تکاليف از اين مَمَر گرفتار می‌بوديم؟ آيا طاقت برداشت موازنۀ بدن بر مفاصل به‌طور فال و بدون سنجش سرهم آمده است؟ نه، هرگز.', source: 'جام و میگر اول'),
  DailyReflection(id: 49, title: 'حکمت داشتن انگشتان درست و منظم', body: 'اگر خداوند جل‌جلاله به بشر نیز مانند حیوانات سُم‌دار انگشتان درست، منظم و صحیح مثلی‌که حالا داریم نمی‌داد و به‌جای آن سُم می‌داشتیم، حال ما انسان‌ها چه می‌بود؟', source: 'جام و میگر اول'),
  DailyReflection(id: 50, title: 'طوالت استخوان‌بندی اتوماتیک', body: 'اگر خدای متعال طوالت استخوان‌بندی ما را توسط ما به اوقات معين، ذريعه لنگرک يا به‌وسيله کش کردن بلند می‌نمود، آيا از ادای اين وظيفه چطور می‌برآمديم؟', source: 'جام و میگر اول'),
  DailyReflection(id: 51, title: 'حکمت موجودیت مواد به اصطلاح گریس بدن', body: 'اگر در داخل استخوان جای برای مغز يا روغن و يا به‌اصطلاح گريس لازم بدن پيدا نمی‌بود، آيا اين استخوان‌ها برای چقدر مدت می‌توانست که از عهدۀ آن برآيد؟', source: 'جام و میگر اول'),
  DailyReflection(id: 52, title: 'حکمت تعدد در خلقت انسانها', body: 'اگر خداوند جل‌جلاله انسان‌ها را به يک‌قواره و يک‌شکل می‌‌آفريد، چه گدودی در نظام زندگی اجتماع واقع می‌شد؟', source: 'جام و میگر اول'),
  DailyReflection(id: 53, title: 'خواب انسجام دهنده انرژی از دست رفته', body: 'اگر خداوند متعال خواب را برای انسجام انرژی ازدست‌رفته جسم مرحمت نمی‌کرد، آيا می‌دانيد که به چه زودی بدن ما از بين می‌رفت و نابود می‌شديم؟', source: 'جام و میگر اول'),
  DailyReflection(id: 54, title: 'حکمت حرارت معتدل جسم', body: 'اگر خداوند جل‌جلاله به‌واسطه اکسيجن هوا و کالوری متنوعۀ غذا، حرارت جسم را به حکمت خاص، معتدل و به اندازۀ لازم گرم نگاه نمی‌کرد، آيا اين حرارت را به چه وسيله می‌توانـستيم تهيه کنيم؟', source: 'جام و میگر اول'),
  DailyReflection(id: 55, title: 'حکمت متابعت از انسان', body: 'اگر خداوند جل‌جلاله به ديده حيوانات اهلی، خورد و کلان، زن و مرد را به يک‌کيفيت نمی‌‌نمود و تا شخص تنومند و کلان به وی نمی‌‌آمد، حيوان به انسان ضعيف متابعت نمی‌کرد؛ آيا بازهم در چنين صورت از حيوانات می‌شد که کار بگيريم و در هرجا بهرۀ لازم از کار و عملش حاصل داريم؟', source: 'جام و میگر اول'),
  DailyReflection(id: 56, title: 'حکمت تعدد خلقت در حیوانات', body: 'اگر خداوند جل‌جلاله همه حیوانات را به یک‌قواره و شکل و چهره خلق می‌فرمود، کی می‌توانست صاحب مال شود؟ زیرا همه یکرنگ بوده، تمییز کرده نمی‌شد؛ حال‌آنکه نه‌تنها در رنگ بلکه قواره و حتی آوازشان تفاوت‌هایی پیدا کرده است تا هرکس مال خود را به نشانی خاص بشناسد.', source: 'جام و میگر اول'),
  DailyReflection(id: 57, title: 'قوت موثر در جسم ضعیف', body: 'اگر خداوند جل‌جلاله پس از بذر حبوبات مثل گندم، جو و غیره به قدرت کبريايی خويش به آن جسم ضعيفش اين قوت مؤثر را نمی‌داد که از زير گِل و حتی سنگ سخت برای خود راه برآمدن را می‌‌يابد، و اين کار  پس از بذر به دوش ما انسان‌ها می‌بود که زمين را چند روز بعد شخمه زده يا نرم کرده مساعد به برآمدن نوک يا ساقۀ حبوبات می‌کرديم، آيا چه تکليف بود و چقدر از دانه‌ها ضايع می‌شد و از ادای اين عمل چه کس يا کسان برآمده می‌توانستند؟', source: 'جام و میگر اول'),
  DailyReflection(id: 58, title: 'لباس انسان مدرن', body: 'اگر خداوند جل‌جلاله از بذر تخم پنبه و کتان و حاصـلات پشم گوسفند و بز و غيره، مواد را به‌دسترس انسان نمی‌گذاشت، امروز دريشی يا لباس مدرن‌‎ترين انسان‌ها بايد از چه می‌بود؟', source: 'جام و میگر اول'),
  DailyReflection(id: 59, title: 'پخته شدن اتوماتیک میوه‌جات', body: 'اگر خداوند جل‌جلاله پُخته شدن میوه‌جات را توسط حرارت آفتاب و مساعدت هوا، به‌طور منظم امروزی سرانجام نمی‌‌بخشيد و رسيدن‌شان را در شاخچه‌ها ذريعۀ حرارت مصنوعی به‌واسطه ما مقرر می‌کرد، آيا از ادای اين عمل چه کس و به چه صورت سرسام‌آور و طاقت‌فرسایی برآمده می‌توانست؟', source: 'جام و میگر اول'),
  DailyReflection(id: 60, title: 'چوب دستک و پل های فریمان', body: 'اگر خداوند جل‌جلاله از زمين این‌همه انواع اشجار مثمر و غيرمثمر را به نام چوب‌دستک و پَل نمی‌کشيد، آيا اين‌همه ابنيۀ بلندبالا، چوکی، ميز، دروازه و غیره لازمه و کارآمد چوب، از کدام مدرک به اين سادگی تهيه و تکافو می‌گرديد؟', source: 'جام و میگر اول'),
  DailyReflection(id: 61, title: 'رشد اتوماتیک اشجار', body: 'اگر خداوند جل‌جلاله اشجار را به‌واسطه کش کردن انسان‌ها رشد می‌داد و خودبه‌خود به‌شکل اتومات و لازمی‌ طوري که امروز می‌‌بينيد بالا نمی‌رفتند و انسان آن‌ها را يکايک به مواقع لازم به‌زعم يا تجربه خود بايد از زمين به کش کردن کلان می‌کرد و به قد آن‌ افزايش می‌داد، در آن صورت چقدر مشکل بود و چطور ما به ادای آن کار موفق می‌شديم؟', source: 'جام و میگر اول'),
  DailyReflection(id: 62, title: 'سبز و تازه بودن اتوماتیک اشجار', body: 'اگر خداوند جل‌جلاله به‌طور اتوماتيک اشجار را تر و تازه و سبز نگه نمی‌داشت و ما شخصـاً بر شاخ و تنۀ آن بايد آب مي‌زديم تا تر و تازه بماند، دقت کنيد چه تکليف مالايطاق بوده و چطور انجام می‌‌يافت؟', source: 'جام و میگر اول'),
  DailyReflection(id: 63, title: 'تربیت شگوفه های درختان', body: 'اگر خداوند جل‌جلاله شگوفه را بعد از برآمدن توسط نگهداری و دقت کردن يا به صورت‌های ديگر، تربيتش را به ما می‌گذاشت، يعنی که ما هر شگوفه را نگاه می‌داشتيم، از آن ميوه به‌دست می‌آمد و اگر نگاه نمی‌کرديم می‌‌افتاد، آيا چقدر شگوفه را از يک درخت شخص نگاه کرده می‌توانست؟ دقت کنيد، حاصـلات مفت سرشار همه‌ساله چطور به اين تکليف يا تکاليف ديگر ممکن شده می‌توانست؟', source: 'جام و میگر اول'),
  DailyReflection(id: 64, title: 'خاک مرطوب و چسپناک', body: 'اگر خدای متعال جل‌جلاله خاک را ذريعه آب، مرطوب و چسپناک نمی‌ساخت، آيا اين ديوارها و عمرانات به چه صورت بالا می‌رفت و چطور برای انسان جای آسايش تهيه شده می‌توانست؟', source: 'جام و میگر اول'),
  DailyReflection(id: 65, title: 'سنگهای شکنند', body: 'اگر خداوند جل‌جلاله کوه‌ها را يک‌تکه از سنگ‌های ناشکن بهم می‌‌آورد، آيا فرزندان انسان از آن چه استفاده کرده و چطور بر آن راهی به خود در عبور و مرور و غیره بهره‌گيری‌ها مهيا کرده می‌توانستند؟', source: 'جام و میگر اول'),
  DailyReflection(id: 66, title: 'ذخیره آبی', body: 'اگر خداوند جل‌جلاله کوه‌‌ها را تانک‌های ذخيره برف و آب در زمستان نمی‌ساخت، آيا در تابستان و خزان آب از کجا می‌شد و مردم چه می‌کردند؟', source: 'جام و میگر اول'),
  DailyReflection(id: 67, title: 'آفرینش فلزات و معادن در بطن زمین', body: 'اگر خداوند جل‌جلاله فلزات و معادن سربه‌مُهر را در بطن زمين نمی‌‌آفريد، تريويرا و غیره البسه قشنگ مدرنترين هوسرانان، بايد به‌واسطه خارهای دشتی بهم دوخته می‌شد يا چطور؟', source: 'جام و میگر اول'),
  DailyReflection(id: 68, title: 'آب غیر قابل‌نفوذ', body: 'اگر خداوند جل‌جلاله در پشت قشر سطح زمين، طبقه‌ مستحکم غيرقابل‌نفوذ آب را خلق نمی‌کرد، آيا اين‌همه بحرها و درياها چطور به روی زمين مستقر و ثابت مانده می‌‌توانستند؟ زيرا خاک خاصيت جذب آب و غیره مايعات را فطرتـاً دارد.', source: 'جام و میگر اول'),
  DailyReflection(id: 69, title: 'زمین غیرقابل جذب در مقابل نفت', body: 'اگر خدای متعال جل‌جلاله خاصيت زمين را به مقابل پطرول و نفت و غیره روغنيات که در بطن آن‌اند، غيرقابل‌جذب نمی‌کرد، آيا اين ذخاير نفتی که میلیون‌ها بيرل روزانه کشيده می‌شود، بازهم زمين آن را جذب نکرده و محفوظ نگهداشته است، باری روزگار مردم وقت ما چه می‌شد؟', source: 'جام و میگر اول'),
  DailyReflection(id: 70, title: 'حایل میانی', body: 'اگر خداوند متعال جل‌جلاله همين دهانه‌های آتشفشان را به داخل زمين، مصادف به معادن نفت و پطرول و غیره روغنيات و گازها می‌کرد و در بين‌شان ]بَرْزَخٌ لَّا يَبْغِيانِ[ را خلق نمی‌‌نمود، آيا حالت زمين چه می‌شد؟', source: 'جام و میگر اول'),
  DailyReflection(id: 71, title: 'آب شور', body: 'اگر خداوند جل‌جلاله آب بحرهای اوقيانوس اطلس، بحرالکاهل و غیره را شور نگه نمی‌داشت، آيا از تعفن بحرها در روی زمين زندگی امکان داشت؟', source: 'جام و میگر اول'),
  DailyReflection(id: 72, title: 'حکمت تبخیر', body: 'اگر خداوند جل‌جلاله آب شور بحرها را به‌واسطۀ تبخير يعنی فلتر هوایی و ابر شيرين نمی‌کرد، آيا بعد از باریدن باران و يا برف اين آب شور کجا قابل‌استفاده بود؟', source: 'جام و میگر اول'),
  DailyReflection(id: 73, title: 'حد لازم برودت هوا در زمستان', body: 'اگر خداوند جل‌جلاله برودت هوا را در زمستان به حد لازم بالا نمی‌برد و يا در هردو قطب زمين، يخچال‌های بزرگ را خلق نمی‌کرد تا به‌واسطه آن حيات اکثر میکروب‌ها نابود و به زندگی‌شان خاتمه داده و يا لااقـل محدود گردد، باری حيات موجودات حيّ، خصوصاً انسان‌های روی زمين چه می‌بود؟', source: 'جام و میگر اول'),
  DailyReflection(id: 74, title: 'حکمت شدت بخشی حرارت در خط استوای زمین', body: 'اگر خدای متعال جلت‌عظمته حرارت را در خط استوای زمين شدت نمی‌‌بخشيد و هکذا در اکثر ممالک به تابستان بالا نمی‌برد، تا بدين ‌وسيله علاوه از نمو و رشد و کمال اشجار، حبوبات، اثمار و همۀ جانداران، باری میکروب‌های زمين نيز به‌واسطه آن نابود نمی‌شد، در چنين صورت حالت ما انسان‌ها چه می‌بود؟', source: 'جام و میگر اول'),
  DailyReflection(id: 75, title: 'نزول باران های موسمی', body: 'اگر خداوند جل‌جلاله به مناطق حارَّه باران‌های موسمی‌ را به نام برسات عندالفرصت نازل نمی‌کرد، باری از شدت گرمی‌ زندگی در آن جای‌ها چطور ممکن بود؟', source: 'جام و میگر اول'),
  DailyReflection(id: 78, title: 'حکمت نزول باران', body: 'اگر خداوند جل‌جلاله باران را از طرف بالا نازل نمی‌کرد تا به‌وسيله آن گرد، خاک، دود و کثافات را که در هوا هميشه متراکم شده از بين ببرد، خصوصاً به عصر امروز از اثر سوخت مواد روغنی در ماشين‌ها و ماشين‌خانه‌ها، کجا زندگی آرام نامسموم به ما انسان‌ها ميسر می‌گرديد؟', source: 'جام و میگر اول'),
  DailyReflection(id: 79, title: 'حکمت معتدل بودن حرارت آفتاب', body: 'اگر خداوند جل‌جلاله حرارت لازمه مناسب را به آفتاب نمی‌داد، آيا ما ساکنان روی زمين چطور زندگی می‌کرديم؟ و به چه قسم اين حرارت ضروری را در کرۀ خود سرانجام نموده و به چه قدرت و زحمت از عهده آن برآمده می‌توانستيم؟', source: 'جام و میگر اول'),
  DailyReflection(id: 80, title: 'حکمت وجود همیشگی آفتاب', body: 'اگر خداوند جل‌جلاله مانند قحطی باران و برف، آفتاب را نيز قحط يعنی گم می‌کرد، باز چه می‌شد؟ و انسان‌ها چه می‌کردند؟', source: 'جام و میگر اول'),
  DailyReflection(id: 81, title: 'حکمت فاصله زمین با آفتاب', body: 'اگر خداوند جل‌جلاله فاصله زمين را با آفتاب به همين پيمانه حاليه نگهداری کرده و مستحکم نمی‌داشت، درحالی‌که اين شمس و همه سيارگان مربوط فلک ما به‌جانب نامعلومی‌ روان‌اند که به روزی تخميناً چندين هزار ميل می‌‌روند.', source: 'جام و میگر اول'),
  DailyReflection(id: 82, title: 'حکمت نزول باران بشکل ریزه‌ای', body: 'اگر خداوند متعال جل‌جلاله باران يا برف يا ژاله را به‌قسم ريزه‌ريزه و دانه‌دانه کم‌کم نازل نمی‌کرد و به‌يکدم ابرها را يخ بسته و به‌شکل کوه‌های آب يا برف يا ژاله سرازير می‌نمود، در آن صورت چه کس يا جاندار به روی زمين زنده و چه تعمير باقی و يا چه شجر سالم مانده می‌توانست؟', source: 'جام و میگر اول'),
];

DailyReflection reflectionForDate(DateTime date) {
  final day = DateTime(date.year, date.month, date.day);
  final origin = DateTime(2024, 1, 1);
  var index = day.difference(origin).inDays % dailyReflections.length;
  if (index < 0) index += dailyReflections.length;
  return dailyReflections[index];
}
